#!/bin/sh
# Writes .env.prod.local for a local production-mode run (docker-compose.prod.local.yml) and CI e2e:
# random secrets, plain HTTP on :8080, fakes via DEMO_FAKES (set in the override file). Keeps an
# existing file unless --force.
set -eu
f=.env.prod.local
if [ -f "$f" ] && [ "${1:-}" != "--force" ]; then echo "$f exists (use --force to regenerate)"; exit 0; fi
rand() { head -c 48 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c "$1"; }
port="${HTTP_PORT:-8080}"
cat > "$f" <<ENV
# Generated by scripts/prod-local-env.sh. Local only, never for a real server.
SITE_ADDRESS=:80
ACME_EMAIL=local@example.invalid
HTTP_PORT=${port}
APP_URL=http://localhost:${port}
LAVIGO_IMAGE=${LAVIGO_IMAGE:-lavigo-os:local}
AUTH_SECRET=$(rand 48)
POSTGRES_PASSWORD=$(rand 32)
SEED_OWNER_EMAIL=owner@lavigo.local
SEED_OWNER_PASSWORD=$(rand 20)
SEED_STAFF_PASSWORD=$(rand 20)
ENV
echo "wrote $f"
